package app.materialclock.ui.sheets import androidx.compose.foundation.layout.* import androidx.compose.foundation.rememberScrollState import androidx.compose.foundation.verticalScroll import androidx.compose.material3.* import androidx.compose.runtime.* import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.unit.dp import app.materialclock.data.Settings @OptIn(ExperimentalMaterial3Api::class) @Composable fun SettingsSheet( settings: Settings, onDismiss: () -> Unit, onSettingsChange: (Settings) -> Unit ) { ModalBottomSheet( onDismissRequest = onDismiss, sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true) ) { Column( modifier = Modifier .fillMaxWidth() .padding(horizontal = 24.dp, vertical = 16.dp) .verticalScroll(rememberScrollState()) ) { Text( text = "App Settings", style = MaterialTheme.typography.headlineMedium, modifier = Modifier.padding(bottom = 20.dp) ) Row( modifier = Modifier .fillMaxWidth() .padding(vertical = 10.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { Column(modifier = Modifier.weight(1f)) { Text("One-Handed Mode", style = MaterialTheme.typography.titleMedium) Text( "Positions elements closer to thumb reach", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant ) } Switch( checked = settings.enableOneHandedMode, onCheckedChange = { onSettingsChange(settings.copy(enableOneHandedMode = it)) } ) } Spacer(modifier = Modifier.height(12.dp)) Row( modifier = Modifier .fillMaxWidth() .padding(vertical = 10.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { Column(modifier = Modifier.weight(1f)) { Text("Frosted Glass Effect", style = MaterialTheme.typography.titleMedium) Text( "Applies translucent blur background styling", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant ) } Switch( checked = settings.enableFrostedGlass, onCheckedChange = { onSettingsChange(settings.copy(enableFrostedGlass = it)) } ) } Spacer(modifier = Modifier.height(12.dp)) Row( modifier = Modifier .fillMaxWidth() .padding(vertical = 10.dp), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { Column(modifier = Modifier.weight(1f)) { Text("Dynamic Colors (Material You)", style = MaterialTheme.typography.titleMedium) Text( "Adapt app colors to device wallpaper", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant ) } Switch( checked = settings.dynamicColors, onCheckedChange = { onSettingsChange(settings.copy(dynamicColors = it)) } ) } Spacer(modifier = Modifier.height(12.dp)) Column(modifier = Modifier.padding(vertical = 10.dp)) { Text( text = "Focus Mode Duration: ${settings.focusModeDurationMinutes} min", style = MaterialTheme.typography.titleMedium ) Slider( value = settings.focusModeDurationMinutes.toFloat(), onValueChange = { onSettingsChange(settings.copy(focusModeDurationMinutes = it.toInt())) }, valueRange = 10f..120f, steps = 10 ) } Spacer(modifier = Modifier.height(12.dp)) Column(modifier = Modifier.padding(vertical = 10.dp)) { Text( text = "Default Alarm Volume: ${(settings.alarmVolume * 100).toInt()}%", style = MaterialTheme.typography.titleMedium ) Slider( value = settings.alarmVolume, onValueChange = { onSettingsChange(settings.copy(alarmVolume = it)) }, valueRange = 0f..1f ) } Spacer(modifier = Modifier.height(32.dp)) } } } 